export const WIDGET_RUNTIME_JS = "// The little programs of the widgets (countdown, order on WhatsApp, copy the UPI id, booking dates). Plain DOM code: the same text runs in the app,\n// in the React project and, turned into plain JavaScript (scripts/gen-runtime.mjs), in the standalone and static exports.\n// the boxes that already have their listeners (kept here, not in the page: an exported page must be wired again when it opens)\nconst wiredBoxes = new WeakSet();\nconst wPad = (n) => String(n).padStart(2, '0');\nfunction initWidgets(root = document) {\n    const timers = [];\n    const stops = [];\n    // a countdown to a date: days, hours, minutes, seconds; \"Offer ended\" when it is over\n    root.querySelectorAll('[data-countdown]').forEach((el) => {\n        const end = Date.parse(el.dataset.countdown ?? '');\n        if (!end)\n            return;\n        const tick = () => {\n            const left = end - Date.now();\n            if (left <= 0) {\n                el.textContent = 'Offer ended';\n                return;\n            }\n            const s = Math.floor(left / 1000);\n            el.textContent = `${Math.floor(s / 86400)}d ${wPad(Math.floor((s % 86400) / 3600))}h ${wPad(Math.floor((s % 3600) / 60))}m ${wPad(s % 60)}s`;\n        };\n        tick();\n        timers.push(window.setInterval(tick, 1000));\n    });\n    // a booking form cannot ask for a day that is gone\n    const today = new Date();\n    const iso = `${today.getFullYear()}-${wPad(today.getMonth() + 1)}-${wPad(today.getDate())}`;\n    root.querySelectorAll('input[type=\"date\"][data-future]').forEach((input) => (input.min = iso));\n    // the order list: quantities, the total, and the message that goes to WhatsApp (or the mail program)\n    root.querySelectorAll('[data-order]').forEach((box) => {\n        if (wiredBoxes.has(box))\n            return;\n        wiredBoxes.add(box);\n        const rows = [...box.querySelectorAll('[data-item]')];\n        const total = box.querySelector('[data-total]');\n        const note = box.querySelector('[data-order-note]');\n        const symbol = box.dataset.symbol ?? '';\n        const qty = (row) => Number(row.querySelector('[data-qty]')?.textContent ?? 0);\n        const refresh = () => {\n            const sum = rows.reduce((a, row) => a + qty(row) * Number(row.dataset.price ?? 0), 0);\n            if (total)\n                total.textContent = sum ? `${symbol}${sum.toLocaleString('en-IN')}` : '-';\n        };\n        const onClick = (event) => {\n            const target = event.target;\n            const step = target.closest('[data-step]');\n            if (step && box.contains(step)) {\n                const row = step.closest('[data-item]');\n                const q = row?.querySelector('[data-qty]');\n                if (row && q)\n                    q.textContent = String(Math.max(0, Math.min(99, qty(row) + Number(step.dataset.step))));\n                refresh();\n                return;\n            }\n            if (!target.closest('[data-send]'))\n                return;\n            const chosen = rows.filter((row) => qty(row) > 0);\n            if (!chosen.length) {\n                if (note)\n                    note.textContent = 'Choose at least one item first.';\n                return;\n            }\n            const lines = chosen.map((row) => `${qty(row)} x ${row.dataset.name}${Number(row.dataset.price) ? ` (${symbol}${Number(row.dataset.price) * qty(row)})` : ''}`);\n            const text = `New order for ${box.dataset.brand ?? 'the shop'}\\n${lines.join('\\n')}${total?.textContent && total.textContent !== '-' ? `\\nTotal: ${total.textContent}` : ''}`;\n            if (box.dataset.wa)\n                window.open(`https://wa.me/${box.dataset.wa}?text=${encodeURIComponent(text)}`, '_blank', 'noopener');\n            else if (box.dataset.email)\n                window.location.href = `mailto:${box.dataset.email}?subject=${encodeURIComponent(`Order for ${box.dataset.brand ?? ''}`)}&body=${encodeURIComponent(text)}`;\n            else if (note)\n                note.textContent = 'There is no WhatsApp number or email to send this to yet.';\n        };\n        box.addEventListener('click', onClick);\n        stops.push(() => box.removeEventListener('click', onClick));\n        refresh();\n    });\n    // copy the UPI id\n    const onCopy = (event) => {\n        const button = event.target.closest('[data-copy]');\n        if (!button)\n            return;\n        const text = button.dataset.copy ?? '';\n        void navigator.clipboard?.writeText(text).then(() => {\n            const old = button.textContent;\n            button.textContent = 'Copied';\n            window.setTimeout(() => (button.textContent = old), 1500);\n        });\n    };\n    const host = root;\n    if (host.addEventListener) {\n        host.addEventListener('click', onCopy);\n        stops.push(() => host.removeEventListener('click', onCopy));\n    }\n    return () => {\n        timers.forEach((t) => window.clearInterval(t));\n        stops.forEach((s) => s());\n    };\n}"
